-- Tier 1 city batch seed: Portland, Austin, Madrid, Lisbon, Copenhagen, Rotterdam, Toronto, Osaka, Shanghai
-- Additive and re-runnable. Apply manually in Supabase SQL Editor.
-- Coordinates and place names were source-checked against OpenStreetMap Nominatim before writing this seed.

insert into public.city_packs (slug, name, route_note, finish_label, safety_note, is_active)
values
  ('portland', 'Portland', 'River crossings, eastside neighborhoods, and regional towns from the core to the valley edge.', 'Portland Tier 1 sheet complete.', 'Ride inside local laws, use marked streets and paths, and keep every checkpoint safe and public.', true),
  ('austin', 'Austin', 'Central neighborhoods, creek parks, and hill country edges across the Austin metro.', 'Austin Tier 1 sheet complete.', 'Ride inside local laws, watch heat and traffic, and use safe public approaches.', true),
  ('madrid', 'Madrid', 'Madrid core districts, transit edges, and outer municipalities across the metro.', 'Madrid Tier 1 sheet complete.', 'Ride inside local laws, stay predictable around traffic, and keep checkpoints public.', true),
  ('lisbon', 'Lisbon', 'Riverfront districts, bridge approaches, and coastal towns around the Lisbon metro.', 'Lisbon Tier 1 sheet complete.', 'Ride inside local laws, respect ferry and bridge limits, and use safe public approaches.', true),
  ('copenhagen', 'Copenhagen', 'Bike-heavy districts, harbor edges, and Zealand towns around Copenhagen.', 'Copenhagen Tier 1 sheet complete.', 'Ride inside local laws, follow cycleway rules, and keep checkpoints on public routes.', true),
  ('rotterdam', 'Rotterdam', 'Port-city districts, river crossings, and Randstad towns around Rotterdam.', 'Rotterdam Tier 1 sheet complete.', 'Ride inside local laws, watch bridge and tram traffic, and keep every stop public.', true),
  ('toronto', 'Toronto', 'Downtown neighborhoods, lakefront parks, and Greater Toronto municipalities.', 'Toronto Tier 1 sheet complete.', 'Ride inside local laws, use public roads and trails, and stay alert in traffic.', true),
  ('osaka', 'Osaka', 'Central wards, neighboring cities, and Kansai rail-linked checkpoints around Osaka.', 'Osaka Tier 1 sheet complete.', 'Ride inside local laws, respect station areas, and use safe public approaches.', true),
  ('shanghai', 'Shanghai', 'Central districts, Pudong corridors, and outer Shanghai towns across the metro.', 'Shanghai Tier 1 sheet complete.', 'Ride inside local laws, stay predictable in traffic, and use public checkpoints only.', true)
on conflict (slug) do update
set
  name = excluded.name,
  route_note = excluded.route_note,
  finish_label = excluded.finish_label,
  safety_note = excluded.safety_note,
  is_active = excluded.is_active,
  updated_at = now();

with pack_refs as (
  select id, slug from public.city_packs where slug in ('portland', 'austin', 'madrid', 'lisbon', 'copenhagen', 'rotterdam', 'toronto', 'osaka', 'shanghai')
)
insert into public.city_checkpoints (
  pack_id,
  slug,
  name,
  lat,
  lng,
  district,
  category,
  vibe,
  hint,
  task_local,
  task_fast,
  task_chaotic,
  sort_weight,
  is_active
)
